<?php
require_once __DIR__.'/../includes/functions.php';require_role(['super_admin','admin','staff']);$db=db();$q=trim((string)($_GET['q']??''));$sql="SELECT p.*,COALESCE(NULLIF(p.full_name,''),u.name,'Walk-in patient') patient_name,COALESCE(NULLIF(p.phone,''),u.phone,'') patient_phone,COALESCE(p.email,u.email) email,du.name assigned_doctor_name FROM patients p LEFT JOIN users u ON u.id=p.user_id LEFT JOIN doctors d ON d.id=p.assigned_doctor_id LEFT JOIN users du ON du.id=d.user_id";$params=[];if($q!==''){$sql.=" WHERE p.patient_number LIKE ? OR COALESCE(p.full_name,u.name,'') LIKE ? OR COALESCE(p.phone,u.phone,'') LIKE ? OR COALESCE(p.email,u.email) LIKE ?";$like='%'.$q.'%';$params=[$like,$like,$like,$like];}$sql.=' ORDER BY p.created_at DESC LIMIT 200';$s=$db->prepare($sql);$s->execute($params);$patients=$s->fetchAll();$pageTitle='Patients';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/page.php';page_heading('Patient directory','Patients','Secure patient profiles and registration records','<a class="btn btn-primary" href="'.e(url('patients/register.php')).'"><i class="bi bi-person-plus me-1"></i>Register patient</a>');?>
<div class="card"><div class="card-header"><form class="d-flex gap-2" method="get"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Search name, patient number, phone or email"><button class="btn btn-outline-primary">Search</button><?php if($q):?><a class="btn btn-light" href="<?=e(url('patients/index.php'))?>">Clear</a><?php endif;?></form></div><div class="table-responsive"><table class="table"><thead><tr><th>Patient</th><th>Patient ID</th><th>Contact</th><th>Assigned doctor</th><th>Date of birth</th><th>Gender</th><th>Registered</th></tr></thead><tbody><?php foreach($patients as $p):?><tr><td><strong><?=e($p['patient_name'])?></strong><div class="small-muted"><?=e($p['email']??'Walk-in record')?></div></td><td><code><?=e($p['patient_number'])?></code></td><td><?=e($p['patient_phone'])?></td><td><?=e($p['assigned_doctor_name']??'Not assigned')?></td><td><?=e($p['date_of_birth'])?></td><td><?=e($p['gender'])?></td><td><?=e(substr($p['created_at'],0,10))?></td></tr><?php endforeach;?><?php if(!$patients)echo empty_row(7,'No matching patients.');?></tbody></table></div><div class="card-footer bg-white small-muted">Showing up to 200 records. Access is limited by role.</div></div><?php require __DIR__.'/../includes/footer.php';?>